ow:before{content:'';width:24px;height:2px;background:var(--blue)}.hero .eyebrow{margin-bottom:8px}h1{max-width:700px;margin:0 0 32px;font-size:clamp(42px,6vw,76px)}h1 span{color:var(--blue)}.hero p{max-width:650px;color:#1f2937;font-size:19px;line-height:1.7}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}.note{margin-top:18px!important;color:var(--muted)!important;font-size:13px!important}.card{padding:32px;border:1px solid #dbe3ee;border-radius:16px;background:#fff;box-shadow:0 18px 50px #1b3a6a1a}.card label,.tag{color:var(--muted);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.card h2{margin:10px 0 24px;font-size:26px}.flow{display:grid;gap:16px}.flow div{padding:13px;border:1px solid var(--line);border-radius:9px;background:var(--soft);font-size:13px;font-weight:600}.flow b{display:inline-grid;place-items:center;width:25px;height:25px;margin-right:8px;border-radius:50%;color:#fff;background:var(--blue);font-size:12px}.section{padding:92px 0}.section h2{margin:12px 0;font-size:clamp(32px,4vw,48px)}.intro{max-width:680px;color:var(--muted);font-size:17px}.service-grid{display:grid;grid-template-columns:1fr 1fr;gap:38px;margin-top:40px}.panel{padding:32px;border:1px solid var(--line);border-radius:14px}.panel h3{font-size:27px}.panel p{color:var(--muted)}ul{display:grid;gap:16px;margin:26px 0 0;padding:0;list-style:none;font-weight:600}li:before{content:'✓';margin-right:12px;color:var(--blue)}.proofs{display:grid;grid-template-columns:1fr 1fr;gap:14px}.proof{padding:22px;border-radius:12px;background:var(--soft)}.proof strong{display:block;font:30px 'Space Grotesk'}.proof span{color:var(--muted);font-size:13px}.projects{background:var(--soft)}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin-top:40px}.project{display:flex;flex-direction:column;overflow:hidden;border:1px solid var(--line);border-radius:14px;background:#fff}.project img{width:100%;height:190px;object-fit:cover}.project-body{display:flex;flex:1;flex-direction:column;padding:24px}.project h3{margin:9px 0 12px;font-size:24px}.project p{flex:1;margin:0;color:#374151;font-size:14px}.project-points{display:grid;gap:8px;flex:1;margin:0;padding:0;list-style:none}.project-points li{font-size:13px;font-weight:400;line-height:1.45}.project-points li:before{margin-right:7px}.status{width:max-content;margin-top:20px;padding:5px 9px;border-radius:5px;color:#124cc4;background:#e9f1ff;font-size:11px;font-weight:700}.process{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:40px}.process article{padding-top:18px;border-top:2px solid var(--blue)}.process h3{margin:10px 0 7px;font-size:20px}.process p{margin:0;color:var(--muted);font-size:14px}.about{color:#fff;background:var(--navy)}.about .eyebrow{color:#9dbbff}.about .eyebrow:before{background:#9dbbff}.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:70px}.about p{color:#d1d5db;font-size:17px}.stack{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.stack div{padding:15px;border:1px solid #374151;border-radius:8px;font-weight:600}.stack small{display:block;color:#9ca3af;font-size:11px;font-weight:400}.contact{text-align:center}.contact h2{max-width:700px;margin:12px auto 18px}.contact p{max-width:590px;margin:auto;color:var(--muted);font-size:17px}.contact .actions{justify-content:center}footer{padding:24px 0;border-top:1px solid var(--line);color:var(--muted);font-size:13px}footer .wrap{display:flex;justify-content:space-between}@media(max-width:850px){.links{display:none}.hero{min-height:auto;padding:64px 0 72px}.hero-grid,.service-grid,.about-grid{grid-template-columns:1fr;gap:40px}.grid3{grid-template-columns:1fr}.process{grid-template-columns:1fr 1fr}}@media(max-width:520px){.wrap{width:calc(100% - 28px)}.nav{height:68px}.brand small{max-width:170px}.cta{padding:10px;font-size:11px}.hero{padding:70px 0}.hero p{font-size:17px}.proofs,.stack,.process{grid-template-columns:1fr}.section{padding:70px 0}footer .wrap{display:block}}
